// === Tab: mySketch.js ===
let theShader;
let _aryInitRGB = [];
function preload() {
  theShader = loadShader("https://openprocessing.org/sketch/1241262/files/shader.vert", "shader.frag");
}

function setup() {
  let canvasSize;
  if (windowWidth <= windowHeight) {
    canvasSize = windowWidth;
  } else {
    canvasSize = windowHeight;
  }
  createCanvas(canvasSize, canvasSize, WEBGL);
  document.getElementsByTagName('main')[0].style.margin = 0;
  setAttributes('premultipliedAlpha', true);
  frameRate(3000);
  noStroke();
  _aryInitRGB = [random(8*PI), random(20*PI), random(200*PI)];
}

function draw() {
  shader(theShader);

  theShader.setUniform("u_resolution", [width*pixelDensity(), height*pixelDensity()]);
  theShader.setUniform("u_count", frameCount);
  theShader.setUniform("u_initRGB", _aryInitRGB);

  rect(0, 0, width, height);
}

